INSERT INTO `questions` (`id`, `text`, `feedback`, `difficulty`, `answer_counter`, `is_correct_answer`, `category_id`) VALUES (1, 'What is the capital of Australia?', 'Canberra was purpose-built as a compromise between Sydney and Melbourne.', 'EASY', 4, 1, 1);
